# 2026-06-mpileup-depth-cap/compare_d_modes.py
# Diagnostic: compare VarScan consensus results produced under different
# samtools mpileup -d (max depth) caps that were already generated by
# mpileup_depth_sweep.py. Validates whether finite caps (8000/12000/16000)
# change variant FREQUENCIES and the set of positions >= 2%, or only the
# absolute depth magnitude. d=0 (unlimited) is treated as the reference/truth.
# Pure stdlib; reads existing consensus files only, writes nothing.
# Usage: python compare_d_modes.py <amp-pip-dev>/runs/T3_rebuild
import glob
import os
import statistics
import sys

D_VALUES = [0, 8000, 12000, 16000]
REF_D = 0
VARFREQ_THRESHOLD = 2.0  # percent; positions >= this are "called"


def parse_consensus(consensus_path):
    """Parse a VarScan consensus file into {position(int): (depth, varfreq)}.

    depth   = Reads1 + Reads2 (int)
    varfreq = percent of reads supporting the variant (float, '%' stripped)
    """
    by_pos = {}
    with open(consensus_path) as fh:
        next(fh)  # header
        for line in fh:
            cols = line.rstrip("\n").split("\t")
            if len(cols) < 7 or not cols[1].isdigit():
                continue
            pos = int(cols[1])
            reads1 = int(cols[4])
            reads2 = int(cols[5])
            varfreq = float(cols[6].rstrip("%"))
            by_pos[pos] = (reads1 + reads2, varfreq)
    return by_pos


def discover_samples(run_dir):
    """Find samples under <run_dir>/Results/*/depth-sweep/ that have all
    expected d<D>.consensus.vcf files. Returns sorted list of (sample, sweep_dir).
    """
    samples = []
    pattern = os.path.join(run_dir, "Results", "*", "depth-sweep")
    for sweep_dir in sorted(glob.glob(pattern)):
        sample = os.path.basename(os.path.dirname(sweep_dir))
        paths = {d: os.path.join(sweep_dir, "{}.d{}.consensus.vcf".format(sample, d))
                 for d in D_VALUES}
        if all(os.path.isfile(p) for p in paths.values()):
            samples.append((sample, sweep_dir, paths))
    return samples


def compare_mode(ref, mode, d):
    """Compare a finite-d mode dict against the reference (d=0) dict over the
    positions present in BOTH. Returns a dict of summary metrics.
    """
    shared = sorted(set(ref) & set(mode))
    depth_ratios = []
    capped = 0
    abs_vf_diffs = []
    for pos in shared:
        depth_ref, vf_ref = ref[pos]
        depth_mode, vf_mode = mode[pos]
        if depth_ref > 0:
            depth_ratios.append(depth_mode / depth_ref)
        if d > 0 and depth_mode < depth_ref:
            capped += 1  # actually downsampled vs d=0 (incl. spillover), i.e. depth_ratio < 1
        abs_vf_diffs.append(abs(vf_mode - vf_ref))

    truth = {pos for pos in ref if ref[pos][1] >= VARFREQ_THRESHOLD}
    called = {pos for pos in mode if mode[pos][1] >= VARFREQ_THRESHOLD}
    # Gained/lost evaluated over positions comparable to truth.
    gained = sorted(called - truth)
    lost = sorted(truth - called)

    return {
        "n_shared": len(shared),
        "depth_ratio_median": statistics.median(depth_ratios) if depth_ratios else 0.0,
        "depth_ratio_max": max(depth_ratios) if depth_ratios else 0.0,
        "frac_capped": (capped / len(shared)) if shared else 0.0,
        "vf_max_abs_diff": max(abs_vf_diffs) if abs_vf_diffs else 0.0,
        "vf_mean_abs_diff": statistics.mean(abs_vf_diffs) if abs_vf_diffs else 0.0,
        "n_truth": len(truth),
        "n_called": len(called),
        "gained": gained,
        "lost": lost,
    }


def main(argv):
    if len(argv) != 2:
        sys.stderr.write("Usage: python compare_d_modes.py <run_dir>\n")
        return 2
    run_dir = argv[1]

    samples = discover_samples(run_dir)
    if not samples:
        sys.stderr.write(
            "No samples with complete depth-sweep consensus files found under "
            "{}/Results/*/depth-sweep/\n".format(run_dir))
        return 1

    finite_ds = [d for d in D_VALUES if d != REF_D]

    for sample, _sweep_dir, paths in samples:
        modes = {d: parse_consensus(paths[d]) for d in D_VALUES}
        ref = modes[REF_D]
        max_raw_depth = max((depth for depth, _vf in ref.values()), default=0)

        print("=" * 78)
        print("Sample: {}".format(sample))
        print("  positions at d=0: {}   max raw depth (Reads1+Reads2) at d=0: {}".format(
            len(ref), max_raw_depth))
        print("  reference mode: d=0 (unlimited);  VarFreq threshold: {:.1f}%".format(
            VARFREQ_THRESHOLD))
        print("")
        max_depth_by_mode = "   ".join(
            "d={}: {}".format(d, max((depth for depth, _vf in modes[d].values()), default=0))
            for d in D_VALUES)
        print("  max depth (Reads1+Reads2) per mode:  {}".format(max_depth_by_mode))
        header = ("  d      n_shared  depth_ratio(med/max)  frac_capped  "
                  "vf_maxΔpp  vf_meanΔpp  truth  called  gained  lost")
        print(header)
        print("  " + "-" * (len(header) - 2))

        any_crossed = False
        for d in finite_ds:
            r = compare_mode(ref, modes[d], d)
            if r["gained"] or r["lost"]:
                any_crossed = True
            print("  {:<6d} {:>8d}  {:>8.3f}/{:<8.3f}  {:>10.3f}  {:>9.3f}  "
                  "{:>10.4f}  {:>5d}  {:>6d}  {:>6d}  {:>4d}".format(
                      d,
                      r["n_shared"],
                      r["depth_ratio_median"],
                      r["depth_ratio_max"],
                      r["frac_capped"],
                      r["vf_max_abs_diff"],
                      r["vf_mean_abs_diff"],
                      r["n_truth"],
                      r["n_called"],
                      len(r["gained"]),
                      len(r["lost"])))

        if any_crossed:
            print("  TAKEAWAY: at least one position crossed the {:.1f}% threshold "
                  "between modes (see gained/lost above).".format(VARFREQ_THRESHOLD))
        else:
            print("  TAKEAWAY: no position crossed the {:.1f}% threshold across any "
                  "finite cap vs d=0; variant CALLS are stable, only depth differs.".format(
                      VARFREQ_THRESHOLD))
        print("")

    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
